function faction(u){if(u.id==='blackfang_guardian'||u.id.startsWith('dark_elf'))return'Dark Elf';if(u.id.startsWith('feline_'))return'Meowri';if(u.id.startsWith('woodland_'))return'Forest Elf';if(u.id.startsWith('elf_'))return'High Elf';if(u.id==='flower_fairy')return'Fairy';if(u.id.startsWith('centaur_'))return'Centaur';return({dawn:'Dawnward Order',east:'Legends of the East',west:'Wild West',sea:'Seasalt Crew',verdant:'Verdant Covenant',arcane:'Arcane',north:'Frostborn Clans',goblin:'Goblin',orc:'Orc',troll:'Troll'})[u.race||u.faction];}
for(const k of Object.keys(G.TRAITS))delete G.TRAITS[k];Object.assign(G.TRAITS,D);for(const u of G.UNITS){const a=assignments[u.id];if(!a)throw Error('Missing traits: '+u.id);a.faction=faction(u);u.traits=[a.faction,a.attribute,a.temperament];}
// Enemy leaders inherit their updated base identity; keep them out of the playable roster.
for(const [id,d]of Object.entries(root.JourneyBosses?.D||{}))for(const suffix of d.true?['','_2']:['']){const leader=G.BY['boss_'+id+suffix];if(leader)leader.traits=[...(G.BY[d.base]?.traits||[])];}
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),live=b=>b.units.filter(u=>u.hp>0),members=(b,u)=>live(b).filter(v=>v.side===u.side),tier=(counts,id)=>{const d=D[id];return !d?.thresholds.length?0:(counts[id]||0)>=d.thresholds[1]?2:(counts[id]||0)>=d.thresholds[0]?1:0;};
function stats(st,c,s,roster,enemy){const n=root.JourneyRelicsR3?.statCounts?.(s,G.counts(roster),enemy)||G.counts(roster),a=assignments[c.type]?.attribute||G.BY[c.type]?.traits.find(id=>D[id]?.category==='attribute'),k=tier(n,a);st.area=G.BY[c.type].area||0;if(!k)return st;const v=k===2;switch(a){case'Devastator':st.atk*=v?1.2:1.15;break;case'Sentinel':st.defense*=v?1.8:1.6;break;case'Unyielding':st.hp*=v?1.3:1.2;break;case'Trailblazer':st.speed*=v?1.25:1.15;break;case'Predator':st.crit=Math.min(.75,st.crit+(v?.4:.25));break;case'Lookout':st.range*=v?1.2:1.15;break;case'Demolisher':st.area*=v?1.2:1.1;break;}return st;}
function ensure(b){if(b.traits54)return b.traits54;const counts=[0,1].map(side=>G.counts(b.units.filter(u=>u.side===side)));root.JourneyRelicsR3?.traitCounts?.(b,counts);/* R3 relíquias coringa */b.traits54={version:1,counts,zones:[],fallen:[[],[]],arcane:[null,null]};for(const u of b.units){u.t54={tiers:Object.fromEntries((G.BY[u.type]?.traits||[]).map(id=>[id,tier(counts[u.side],id)])),forest:[],centaurDamage:0};if(rank(u,'Verdant Covenant'))b.traits54.zones.push({x:u.x,y:u.y,side:u.side});}for(const u of b.units)if(rank(u,'Dawnward Order')&&members(b,u).some(v=>v!==u&&rank(v,'Dawnward Order')&&dist(u,v)<=100))shield(b,u,u.maxhp*val(u,'Dawnward Order',.08,.14),6);return b.traits54;}
function rank(u,id){return u.t54?.tiers?.[id]||0;}function val(u,id,a,c){const k=rank(u,id);return k===2?c:k===1?a:0;}
function shield(b,u,n,time){const amount=root.JourneyTree?.shield(b,u,n)??n;if(amount>(u.shield||0)||u.shieldTime<=0){u.shield=amount;u.shieldTime=time;}else u.shieldTime=Math.max(u.shieldTime||0,time);}
function initialize(b){ensure(b);return b;}
const build=G.createBattle;G.createBattle=function(s){const b=build(s);if(b)initialize(b);return b;};
function beforeStep(b,dt){ensure(b);for(const u of live(b)){if(!u.t54)u.t54={tiers:{},forest:[],centaurDamage:0};const st=u.t54;if(false&&rank(u,'Protector')&&!st.protected){const ally=members(b,u).find(v=>v!==u&&v.hp/v.maxhp<.3&&dist(u,v)<=100),foes=live(b).filter(v=>v.side!==u.side&&!v.raidBoss&&!(v.taunt>0)&&dist(u,v)<=90);if(ally&&foes.length){st.protected=true;for(const v of foes){v.tauntUid=u.uid;v.taunt=val(u,'Protector',2,3);}G.announce(b,u,'PROTECTOR');}}}}
function choose(b,u,targets){if(!rank(u,'Ruthless'))return null;return targets.filter(t=>dist(u,t)-(t.bodyRadius||0)<=u.range).sort((a,c)=>a.hp/a.maxhp-c.hp/c.maxhp||dist(u,a)-dist(u,c))[0]||null;}
function defense(b,u,n){return n*(rank(u,'Patient')?1+Math.min(u.r3PatientMax||3,Math.floor((b.time+(u.r3PatientT||0))/(u.r3PatientEvery||3)))*val(u,'Patient',0.08,0.15):1)*(u.t54?.shredUntil>b.time?1-(u.t54.shred||0):1);}
function crit(b,u,n){if(rank(u,'Fearless')&&(u.hits||0)>0&&u.hits%(u.hp/u.maxhp<.4?1:val(u,'Fearless',3,2))===0)return 1;return Math.min(.75,n);}
function ignore(b,a,t,skill,n){if(!skill&&rank(a,'Legends of the East')&&a.hits%4===0)n=1-(1-n)*(1-val(a,'Legends of the East',.25,.4));if(rank(a,'Dark Elf')&&t.targetUid&&t.targetUid!==a.uid&&members(b,a).some(u=>u.uid===t.targetUid))n=1-(1-n)*(1-val(a,'Dark Elf',.3,.45));return n;}
function reduction(b,t,n){let g=0;{const pr=live(b).filter(u=>u.side===t.side&&rank(u,'Protector')&&dist(u,t)<=(root.JourneyRelicsR3?.protectorRange?.(b,t.side)||90));if(pr.length)g=Math.max(...pr.map(u=>val(u,'Protector',0.05,0.1)));}const veg=rank(t,'Verdant Covenant')&&b.traits54.zones.some(z=>z.side===t.side&&dist(z,t)<=90)?val(t,'Verdant Covenant',.1,.18):0;return Math.min(.65,1-(1-n)*(1-g)*(1-veg));}
function immune(b,t){return (t.t54?.immuneUntil||0)>b.time;}
function damage(b,a,t,n,skill,options){if(!a.t54)return n;let bonus=0;const st=a.t54;
 if(rank(a,'Audacious')&&!members(b,a).some(v=>v!==a&&dist(a,v)<=90))bonus+=val(a,'Audacious',.15,.25);
 if(rank(a,'Ruthless')&&t.hp/t.maxhp<.3)bonus+=val(a,'Ruthless',.15,.25);if(b.time<6)bonus+=val(a,'Impulsive',.2,.35);
 if(rank(a,'Frostborn Clans'))bonus+=Math.min(3,b.traits54.fallen[a.side].length)*val(a,'Frostborn Clans',.1,.15);
 if(rank(a,'Seasalt Crew')&&(t.t54?.pirates||[]).some(x=>x.side===a.side&&x.type!==a.type&&b.time-x.at<=2))bonus+=val(a,'Seasalt Crew',.12,.2);
 if(!skill){if(rank(a,'Wild West')){if(st.westHit!==a.hits){const target=a.targetUid||t.uid;st.westBonus=st.westTarget===target?Math.min(4,st.westStacks||0):0;st.westStacks=st.westBonus+1;st.westTarget=target;st.westHit=a.hits;}bonus+=st.westBonus*val(a,'Wild West',.05,.08);}if(rank(a,'Forest Elf')&&!st.forest.includes(t.uid)){bonus+=val(a,'Forest Elf',.3,.5);st.forest.push(t.uid);}if(rank(a,'Troll')&&a.hits%(val(a,'Troll',3,2)+1)===0)bonus+=.5;if(st.returnHit===a.hits)bonus+=st.returnPower||0;else if(st.returnPower){st.returnHit=a.hits;bonus+=st.returnPower;st.returnPowerUsed=true;}}
 if(!skill&&rank(a,'Legends of the East')&&a.hits%4===0)bonus+=val(a,'Legends of the East',0.5,0.6);if(rank(a,'Goblin')){const gs=new Set(members(b,a).filter(u=>u!==a&&u.hp>0&&u.type!==a.type&&rank(u,'Goblin')).map(u=>u.type));bonus+=Math.min(3,gs.size)*val(a,'Goblin',0.08,0.08);}if(!skill&&rank(a,'Trailblazer')){const p=st.trail,moved=!p||Math.hypot(a.x-p.x,a.y-p.y)>=30;if(moved&&b.time>=(st.trailReady||0)){bonus+=val(a,'Trailblazer',0.45,0.65);st.trailReady=b.time+4;}st.trail={x:a.x,y:a.y};}if(rank(a,'Patient'))bonus+=Math.min(a.r3PatientMax||3,Math.floor((b.time+(a.r3PatientT||0))/(a.r3PatientEvery||3)))*val(a,'Patient',0.04,0.08);const down=st.atkDownUntil>b.time?.15:0;n*=1+bonus;if(down&&!(a.atkDown>0))n*=1-down;return n;}
function flags(a,skill,options){return{traitOrc:!skill&&!!rank(a,'Orc'),traitTroll:!skill&&!!rank(a,'Troll')&&a.hits%(val(a,'Troll',3,2)+1)===0,dot:!!options.dot};}
function beforeSkill(b,u){const st=u.t54;if(!st)return;const p=b.traits54.arcane[u.side];st.castBoost=1;if(rank(u,'Arcane')&&p&&p.uid!==u.uid){st.castBoost=1+p.bonus;b.traits54.arcane[u.side]=null;}u.skill*=st.castBoost;}
function afterSkill(b,u){const st=u.t54;if(!st)return;if(rank(u,'High Elf')&&!st.elfCast){st.elfCast=true;const ally=members(b,u).filter(v=>v!==u&&rank(v,'High Elf')).sort((a,c)=>a.hp/a.maxhp-c.hp/c.maxhp)[0];if(ally)shield(b,ally,u.maxhp*val(u,'High Elf',.15,.22),4);}if(rank(u,'Arcane'))b.traits54.arcane[u.side]={uid:u.uid,bonus:val(u,'Arcane',.4,.6)};st.castBoost=1;}
function survive(b,u){if(u.hp<=0&&rank(u,'Meowri')&&!u.t54.saved){u.hp=1;u.t54.saved=true;u.t54.immuneUntil=b.time+val(u,'Meowri',.25,.5);G.announce(b,u,'LAST LIFE');}}
