function act(b,u,dt){const st=u.t54,r=st?.retreat;if(!r)return false;if(u.stun>0||u.root>0||u.taunt>0){st.retreat=null;u.motion=null;return true;}const enemies=live(b).filter(v=>v.side!==u.side),target=enemies.find(v=>v.uid===r.uid)||enemies.sort((a,c)=>dist(a,u)-dist(c,u))[0];if(!target){st.retreat=null;u.motion=null;return false;}r.uid=target.uid;
 if(r.phase==='start'){const d=G.direction(target,u),distance=val(u,'Centaur',60,80);G.moveUnit(b,u,{x:u.x+d.x*distance,y:u.y+d.y*distance});if(u.motion)u.motion.life=.35;r.phase='back';}
 else if(!u.motion&&r.phase==='back'){const d=G.direction(target,u),distance=u.range+(target.bodyRadius||0);G.moveUnit(b,u,{x:target.x+d.x*distance,y:target.y+d.y*distance});if(u.motion)u.motion.life=.3;r.phase='forward';}
 else if(!u.motion&&r.phase==='forward'){st.returnPower=val(u,'Centaur',.5,.8);st.returnPowerUsed=false;st.returnHit=-1;st.retreat=null;G.announce(b,u,'GALLOP');return false;}
 if(u.motion){const m=u.motion,k=Math.min(1,dt/Math.max(dt,m.life));u.x+=(m.x-u.x)*k;u.y+=(m.y-u.y)*k;m.life-=dt;if(m.life<=0)u.motion=null;}return true;}
function afterSettle(b,living,pending){for(const p of pending){if(!p.damage||!p.source||!p.target.t54)continue;const t=p.target,st=t.t54,a=p.source;if(p.traitOrc){st.orcStacks=st.shredUntil>b.time?Math.min(5,(st.orcStacks||0)+1):1;st.shred=st.orcStacks*val(a,'Orc',.06,.09);st.shredUntil=b.time+4;}if(p.traitTroll)st.atkDownUntil=b.time+3;if(rank(a,'Seasalt Crew')){st.pirates=(st.pirates||[]).filter(x=>b.time-x.at<=2&&!(x.side===a.side&&x.type===a.type));st.pirates.push({side:a.side,type:a.type,at:b.time});}}
 for(const u of living){if(u.t54?.returnPowerUsed){u.t54.returnPower=0;u.t54.returnPowerUsed=false;}if(u.hp<=0&&rank(u,'Frostborn Clans')&&!b.traits54.fallen[u.side].includes(u.type))b.traits54.fallen[u.side].push(u.type);}}
